from samson.protocols.tls.messages import *
from samson.protocols.tls.tls_client import TLSState, TLSConfiguration
from samson.protocols.tls.ciphersuite import Ciphersuite
from samson.protocols.tls.key_schedule import KeySchedule

#################################################
#                   RFC8448                     #
# https://datatracker.ietf.org/doc/html/rfc8448 #
#################################################

# Configure objects
kex = ECDHE(G=P256.G)

def aes_gcm(key):
    rij = Rijndael(key)
    gcm = GCM(rij)
    return gcm


cs           = Ciphersuite(aes_gcm, SHA256())
config       = TLSConfiguration(kex, cs)
server_state = TLSState(config)
client_state = TLSState(config)


client_hello_bytes = Bytes()
client_hello       = Handshake.deserialize(client_hello_bytes)[1]
assert client_hello.serialize() == client_hello_bytes

server_retry_bytes = Bytes()
server_retry       = Handshake.deserialize(server_retry_bytes)[1]
assert server_retry.serialize() == server_retry_bytes

assert server_retry.message.val.val.random == HELLO_RETRY_MAGIC

client_key = ECDHE(G=P256.G, d=0xab5473467e19346ceb0a0414e41da21d4d2445bc3025afe97c4e8dc8d513da39)
assert client_key.pub.serialize_uncompressed()== Bytes(0x04a6da7392ec591e17abfd535964b99894d13befb221b3def2ebe3830eac8f0151812677c4d6d2237e85cf01d6910cfb83954e76ba7352830534159897e8065780)

client_retry_bytes = Bytes()
client_retry       = Handshake.deserialize(client_retry_bytes)[1]
assert client_retry.serialize() == client_retry_bytes

server_key = ECDHE(G=P256.G, d=0x8c510601f9765bfb8ed693449a48989859b5cfa879cb9f5443c41c5ff10634ed)
assert server_key.pub.serialize_uncompressed() == Bytes(0x04583e054b7a66672ae020ad9d2686fcc85b5ad41a134a0f03ee72b893052bd85b4c8de6776f5b04ac07d83540eab3e3d9c547bc6528c4317d294686093a6cad7d)

server_hello_bytes = Bytes(0x020000770303bb341d847fd789c47c387172dc0c9bf147fccacb5043d86ca4c598d3ff571b9800130100004f003300450017004104583e054b7a66672ae020ad9d2686fcc85b5ad41a134a0f03ee72b893052bd85b4c8de6776f5b04ac07d83540eab3e3d9c547bc6528c4317d294686093a6cad7d002b00020304)
server_hello       = Handshake.deserialize(server_hello_bytes)[1]
assert server_hello.serialize() == server_hello_bytes

shared_key = server_key.derive_key(client_key.pub)

server_state.transcript.append(client_hello)

server_state.key_schedule.process_early_secret(server_state.transcript.hash())
assert server_state.key_schedule[KeySchedule.EARLY_SECRET] == Bytes(0x33ad0a1c607ec03b09e6cd9893680ce210adf300aa1f2660e1b22e10f170f92a)


server_state.transcript.extend([
    server_retry,
    client_retry,
    server_hello
])


server_state.key_schedule.process_handshake_secret(shared_key, server_state.transcript.hash())
assert server_state.key_schedule[KeySchedule.HANDSHAKE_SECRET] == Bytes(0xce022e5e6e81e50736d773f2d3adfce8220d049bf510f0dbfac927ef4243b148)
assert server_state.key_schedule[KeySchedule.CLIENT_HANDSHAKE_TRAFFIC_SECRET] == Bytes(0x158aa7ab8855073582b41d674b4055cabcc534728f659314861b4e08e2011566)
assert server_state.key_schedule[KeySchedule.SERVER_HANDSHAKE_TRAFFIC_SECRET] == Bytes(0x3403e781e2af7b6508da28574f6e95a1abf162de83a97927c37672a4a0cef8a1)


enc_ext_bytes = Bytes(0x080000180016000a0008000600170018001d001c0002400100000000)
enc_ext       = Handshake.deserialize(enc_ext_bytes)[1]
assert enc_ext.serialize() == enc_ext_bytes

server_cert_bytes = Bytes()
server_cert       = Handshake.deserialize(server_cert_bytes)[1]
assert server_cert.serialize() == server_cert_bytes

server_cert_verify_bytes = Bytes(0x0f0000840804008033ab13d4462707231b5dcae6c8190b63d1dabc74f28c395370da0b07e5b83066d0246a31acd95df475bfd799a4a70d33ad93d3a317a9b2c0d237a5685b219e774112e391a247607d1aeff1bbd0a39f382ee1a5fe88ae99ec59228e6497e45d48ce275a6d5ef40d169fb6f9d33b052ed3dcdd6b5a48baafffbcb290128415bd38)
server_cert_verify       = Handshake.deserialize(server_cert_verify_bytes)[1]
assert server_cert_verify.serialize() == server_cert_verify_bytes


server_state.transcript.extend([
    enc_ext,
    server_cert,
    server_cert_verify
])


assert server_state.key_schedule[KeySchedule.SERVER_FINISHED] == Bytes(0xe7f8bb3ea4b6c30c4710b3d09c3313658117e70b097e850368e2510ca5631f74)

server_finished = server_state.finished(server_state.key_schedule[KeySchedule.SERVER_FINISHED])

assert server_finished.serialize() == Bytes(0x140000208863e6bfb0420a927fa27f34336a70ae426e968e3eb884945b96856dba3976d1)


server_state.transcript.append(server_finished)

server_state.key_schedule.process_master_secret(server_state.transcript.hash())
assert server_state.key_schedule[KeySchedule.MASTER_SECRET] == Bytes(0x1131545d0baf79ddce9b87f06945781a57dd18ef378dcd2060f8f9a569027ed8)
assert server_state.key_schedule[KeySchedule.CLIENT_APPLICATION_TRAFFIC_SECRET_0] == Bytes(0x75ecf4b972525aa0dcd057c9944d4cd5d82671d8843141d7dc2a4ff15a21dc51)
assert server_state.key_schedule[KeySchedule.SERVER_APPLICATION_TRAFFIC_SECRET_0] == Bytes(0x5c74f87df04225db0f8209c9de6429e49435fdefa7cad61864874d12f31cfc8d)
assert server_state.get_traffic_key(server_state.key_schedule[KeySchedule.SERVER_HANDSHAKE_TRAFFIC_SECRET]) == (Bytes(0x4646bfac1712c426cd78d8a24a8a6f6b), Bytes(0xc7d395c08d62f297d13768ea))



server_full_bytes     = Bytes()
server_enc_full_bytes = Bytes()
server_enc_full       = TLSPlaintext.deserialize(server_enc_full_bytes)[1]
assert server_enc_full.serialize() == server_enc_full_bytes


server_dec_full = server_state.decrypt_application_data(server_state.key_schedule[KeySchedule.SERVER_HANDSHAKE_TRAFFIC_SECRET], server_enc_full)
assert server_dec_full.serialize() == (server_full_bytes + b'\x16')

server_reenc_full = server_state.encrypt_application_data(server_state.key_schedule[KeySchedule.SERVER_HANDSHAKE_TRAFFIC_SECRET], server_dec_full)
assert server_reenc_full.serialize() == server_enc_full_bytes

assert server_state.key_schedule[KeySchedule.EXPORTER_MASTER_SECRET] == Bytes(0x7c06d3ae106a3a374ace4837b3985cac67780a6e2c5c04b58319d584df09d223)
assert server_state.get_traffic_key(server_state.key_schedule[KeySchedule.SERVER_APPLICATION_TRAFFIC_SECRET_0]) == (Bytes(0xf27a5d97bd25550c4823b0f3e5d29388), Bytes(0x0dd631f7b71cbbc797c35fe7))
assert server_state.get_traffic_key(server_state.key_schedule[KeySchedule.CLIENT_HANDSHAKE_TRAFFIC_SECRET]) == (Bytes(0x2f1f918663d590e7421149a29d94b0b6), Bytes(0x414d5485235e1a688793bd74))



client_state.transcript.append(client_hello)
client_state.key_schedule.process_early_secret(client_state.transcript.hash())

client_state.transcript.extend([
    server_retry,
    client_retry,
    server_hello
])
client_state.key_schedule.process_handshake_secret(shared_key, client_state.transcript.hash())


client_state.transcript.extend([
    enc_ext,
    server_cert,
    server_cert_verify
])

client_state.transcript.append(server_finished)
client_state.key_schedule.process_master_secret(client_state.transcript.hash())

keys_to_check = [
    KeySchedule.EARLY_SECRET,
    KeySchedule.HANDSHAKE_SECRET,
    KeySchedule.MASTER_SECRET,
    KeySchedule.CLIENT_HANDSHAKE_TRAFFIC_SECRET,
    KeySchedule.SERVER_HANDSHAKE_TRAFFIC_SECRET,
    KeySchedule.CLIENT_APPLICATION_TRAFFIC_SECRET_0,
    KeySchedule.SERVER_APPLICATION_TRAFFIC_SECRET_0,
    KeySchedule.CLIENT_FINISHED,
    KeySchedule.SERVER_FINISHED
]

for key_name in keys_to_check:
    assert client_state.key_schedule[key_name] == server_state.key_schedule[key_name]


client_finished = client_state.finished(client_state.key_schedule[KeySchedule.CLIENT_FINISHED])
assert client_finished.serialize() == Bytes(0x1400002023f52fdb0709a55bd7f79b991f25484087bcfd4d4380b12326a52a28b2e368e1)
assert client_state.get_traffic_key(client_state.key_schedule[KeySchedule.CLIENT_APPLICATION_TRAFFIC_SECRET_0]) == (Bytes(0xa7eb2a0525eb4331d58fcbf9f7ca2e9c),  Bytes(0x86e8be227c1bd2b3e39cb444))


enc_client_alert_bytes = Bytes(0x17030300132ea6cdf749196023e2b3a49491695536426047)
enc_client_alert       = TLSPlaintext.deserialize(enc_client_alert_bytes)[1]
assert enc_client_alert.serialize() == enc_client_alert_bytes

dec_client_alert   = server_state.decrypt_application_data(server_state.key_schedule[KeySchedule.CLIENT_APPLICATION_TRAFFIC_SECRET_0], enc_client_alert)
reenc_client_alert = server_state.encrypt_application_data(server_state.key_schedule[KeySchedule.CLIENT_APPLICATION_TRAFFIC_SECRET_0], dec_client_alert)
assert reenc_client_alert.serialize() == enc_client_alert_bytes


enc_server_alert_bytes = Bytes(0x1703030013519fc5075cb0884349759ff9ef6f011bb4c6f2)
enc_server_alert       = TLSPlaintext.deserialize(enc_server_alert_bytes)[1]
assert enc_server_alert.serialize() == enc_server_alert_bytes

dec_server_alert   = client_state.decrypt_application_data(client_state.key_schedule[KeySchedule.SERVER_APPLICATION_TRAFFIC_SECRET_0], enc_server_alert)
reenc_server_alert = client_state.encrypt_application_data(client_state.key_schedule[KeySchedule.SERVER_APPLICATION_TRAFFIC_SECRET_0], dec_server_alert)
assert reenc_server_alert.serialize() == enc_server_alert_bytes
